import json
from pathlib import Path
from typing import Any, Dict, Mapping, Optional


class ConfigLoader:
    """Load configuration for different deployment stages.

    The class can be initialised with a path to a JSON configuration file.
    If no path is provided, a built‑in default configuration is used.
    The :meth:`get_settings` method returns the configuration block for the
    requested stage (e.g. ``'dev'``, ``'staging'`` or ``'prod'``).

    Example
    -------
    >>> loader = ConfigLoader()
    >>> dev_cfg = loader.get_settings('dev')
    >>> dev_cfg['database']['host']
    'localhost'
    """

    _default_config: Mapping[str, Mapping[str, Any]] = {
        'dev': {
            'database': {
                'host': 'localhost',
                'port': 5432,
                'user': 'dev_user',
                'password': 'dev_pass',
                'name': 'myapp_dev',
            },
            'logging': {
                'level': 'DEBUG',
                'handlers': ['console'],
            },
            'feature_flags': {
                'new_ui': False,
            },
        },
        'staging': {
            'database': {
                'host': 'staging-db.mycompany.com',
                'port': 5432,
                'user': 'staging_user',
                'password': 'staging_pass',
                'name': 'myapp_staging',
            },
            'logging': {
                'level': 'INFO',
                'handlers': ['file'],
            },
            'feature_flags': {
                'new_ui': True,
            },
        },
        'prod': {
            'database': {
                'host': 'prod-db.mycompany.com',
                'port': 5432,
                'user': 'prod_user',
                'password': 'prod_pass',
                'name': 'myapp',
            },
            'logging': {
                'level': 'WARNING',
                'handlers': ['file', 'syslog'],
            },
            'feature_flags': {
                'new_ui': True,
            },
        },
    }

    def __init__(self, config_path: Optional[str] = None) -> None:
        """Create a new loader.

        Parameters
        ----------
        config_path: Optional[str]
            Path to a JSON file that contains a mapping of stages to their
            configuration blocks. If ``None``, the built‑in default configuration
            is used.
        """
        if config_path:
            self._config = self._load_from_file(Path(config_path))
        else:
            # Copy the default to avoid accidental mutation of the class attribute.
            self._config = {stage: dict(settings) for stage, settings in self._default_config.items()}

    @staticmethod
    def _load_from_file(path: Path) -> Dict[str, Any]:
        """Read a JSON configuration file.

        The file must contain a top‑level JSON object where each key is a stage
        name and each value is the configuration dictionary for that stage.

        Parameters
        ----------
        path: Path
            Location of the JSON file.

        Returns
        -------
        Dict[str, Any]
            Parsed configuration mapping.
        """
        if not path.is_file():
            raise FileNotFoundError(f'Configuration file not found: {path}')
        with path.open('r', encoding='utf-8') as fh:
            data = json.load(fh)

        if not isinstance(data, dict):
            raise ValueError('Configuration file must contain a JSON object at the top level')
        return data

    def get_settings(self, stage: str) -> Dict[str, Any]:
        """Return the configuration block for the requested stage.

        Parameters
        ----------
        stage: str
            Name of the deployment stage (e.g. ``'dev'``, ``'staging'`` or ``'prod'``).

        Returns
        -------
        Dict[str, Any]
            Configuration dictionary for the stage.

        Raises
        ------
        KeyError
            If the requested stage does not exist in the configuration.
        """
        try:
            # Return a shallow copy so the caller cannot modify the internal state.
            return dict(self._config[stage])
        except KeyError as exc:
            raise KeyError(f'Unknown stage: {stage!r}') from exc
